CREATE TYPE "DocumentReviewStatus" AS ENUM ('PENDING','PROCESSING','PASSED','FAILED','NEEDS_REVIEW');
CREATE TYPE "VerificationType" AS ENUM ('IDENTITY','NEED','INSTITUTION','PAYMENT_DESTINATION','ENHANCED');
CREATE TYPE "SanctionsStatus" AS ENUM ('PENDING','CLEAR','MATCH','REVIEW_REQUIRED','FAILED');
CREATE TYPE "SafeguardingStatus" AS ENUM ('OPEN','TRIAGED','INVESTIGATING','RESOLVED');
CREATE TYPE "CommunicationType" AS ENUM ('VOICE','VIDEO');
CREATE TYPE "PaymentProviderType" AS ENUM ('MPESA','CARD','BANK_TRANSFER','OTHER');
CREATE TABLE "DocumentCheck"("id" TEXT NOT NULL,"evidenceId" TEXT NOT NULL,"status" "DocumentReviewStatus" NOT NULL DEFAULT 'PENDING',"ocrTextEncrypted" TEXT,"extractedData" JSONB,"tamperSignals" JSONB,"providerReference" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DocumentCheck_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "DocumentCheck_evidenceId_key" ON "DocumentCheck"("evidenceId");
CREATE TABLE "IdentityVerification"("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"type" "VerificationType" NOT NULL,"provider" TEXT NOT NULL,"status" "VerificationStatus" NOT NULL DEFAULT 'PENDING',"providerReference" TEXT,"countryCode" TEXT NOT NULL,"documentType" TEXT,"documentLast4" TEXT,"reason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "IdentityVerification_pkey" PRIMARY KEY("id"));
CREATE INDEX "IdentityVerification_userId_status_idx" ON "IdentityVerification"("userId","status");
CREATE TABLE "InstitutionVerification"("id" TEXT NOT NULL,"caseId" TEXT NOT NULL,"institutionName" TEXT NOT NULL,"institutionType" TEXT NOT NULL,"provider" TEXT NOT NULL,"status" "VerificationStatus" NOT NULL DEFAULT 'PENDING',"providerReference" TEXT,"evidence" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "InstitutionVerification_pkey" PRIMARY KEY("id"));
CREATE INDEX "InstitutionVerification_caseId_status_idx" ON "InstitutionVerification"("caseId","status");
CREATE TABLE "SanctionsScreening"("id" TEXT NOT NULL,"userId" TEXT,"caseId" TEXT,"provider" TEXT NOT NULL,"status" "SanctionsStatus" NOT NULL DEFAULT 'PENDING',"providerReference" TEXT,"result" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SanctionsScreening_pkey" PRIMARY KEY("id"));
CREATE INDEX "SanctionsScreening_status_createdAt_idx" ON "SanctionsScreening"("status","createdAt");
CREATE TABLE "FraudGraphNode"("id" TEXT NOT NULL,"type" TEXT NOT NULL,"valueHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "FraudGraphNode_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "FraudGraphNode_type_valueHash_key" ON "FraudGraphNode"("type","valueHash");
CREATE TABLE "FraudGraphEdge"("id" TEXT NOT NULL,"fromId" TEXT NOT NULL,"toId" TEXT NOT NULL,"relation" TEXT NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "FraudGraphEdge_pkey" PRIMARY KEY("id"));
CREATE INDEX "FraudGraphEdge_fromId_relation_idx" ON "FraudGraphEdge"("fromId","relation"); CREATE INDEX "FraudGraphEdge_toId_relation_idx" ON "FraudGraphEdge"("toId","relation");
CREATE TABLE "DeviceRegistration"("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"deviceHash" TEXT NOT NULL,"platform" TEXT NOT NULL,"pushToken" TEXT,"lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DeviceRegistration_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "DeviceRegistration_userId_deviceHash_key" ON "DeviceRegistration"("userId","deviceHash");
CREATE TABLE "CommunicationRoom"("id" TEXT NOT NULL,"type" "CommunicationType" NOT NULL,"provider" TEXT NOT NULL,"providerRoomId" TEXT,"caseId" TEXT,"createdById" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" TIMESTAMP(3),CONSTRAINT "CommunicationRoom_pkey" PRIMARY KEY("id"));
CREATE INDEX "CommunicationRoom_caseId_status_idx" ON "CommunicationRoom"("caseId","status");
CREATE TABLE "SafeguardingCase"("id" TEXT NOT NULL,"reportId" TEXT NOT NULL,"status" "SafeguardingStatus" NOT NULL DEFAULT 'OPEN',"priority" TEXT NOT NULL DEFAULT 'NORMAL',"assignedToId" TEXT,"actionPlan" TEXT,"resolvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SafeguardingCase_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "SafeguardingCase_reportId_key" ON "SafeguardingCase"("reportId"); CREATE INDEX "SafeguardingCase_status_priority_createdAt_idx" ON "SafeguardingCase"("status","priority","createdAt");
CREATE TABLE "PaymentProvider"("id" TEXT NOT NULL,"countryCode" TEXT NOT NULL,"type" "PaymentProviderType" NOT NULL,"name" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT false,"settlementCurrency" TEXT NOT NULL,"configRef" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PaymentProvider_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "PaymentProvider_countryCode_type_name_key" ON "PaymentProvider"("countryCode","type","name");
CREATE TABLE "PaymentAttempt"("id" TEXT NOT NULL,"transactionId" TEXT NOT NULL,"providerId" TEXT NOT NULL,"providerReference" TEXT,"status" TEXT NOT NULL DEFAULT 'CREATED',"requestHash" TEXT,"responseMeta" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PaymentAttempt_pkey" PRIMARY KEY("id"));
CREATE INDEX "PaymentAttempt_transactionId_status_idx" ON "PaymentAttempt"("transactionId","status");
CREATE TABLE "ExchangeRateSnapshot"("id" TEXT NOT NULL,"baseCurrency" TEXT NOT NULL,"quoteCurrency" TEXT NOT NULL,"rate" DECIMAL(20,10) NOT NULL,"source" TEXT NOT NULL,"capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ExchangeRateSnapshot_pkey" PRIMARY KEY("id"));
CREATE INDEX "ExchangeRateSnapshot_baseCurrency_quoteCurrency_capturedAt_idx" ON "ExchangeRateSnapshot"("baseCurrency","quoteCurrency","capturedAt");
ALTER TABLE "DocumentCheck" ADD CONSTRAINT "DocumentCheck_evidenceId_fkey" FOREIGN KEY("evidenceId") REFERENCES "CaseEvidence"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "IdentityVerification" ADD CONSTRAINT "IdentityVerification_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "InstitutionVerification" ADD CONSTRAINT "InstitutionVerification_caseId_fkey" FOREIGN KEY("caseId") REFERENCES "HelpCase"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SanctionsScreening" ADD CONSTRAINT "SanctionsScreening_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "SanctionsScreening" ADD CONSTRAINT "SanctionsScreening_caseId_fkey" FOREIGN KEY("caseId") REFERENCES "HelpCase"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "FraudGraphEdge" ADD CONSTRAINT "FraudGraphEdge_fromId_fkey" FOREIGN KEY("fromId") REFERENCES "FraudGraphNode"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FraudGraphEdge" ADD CONSTRAINT "FraudGraphEdge_toId_fkey" FOREIGN KEY("toId") REFERENCES "FraudGraphNode"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DeviceRegistration" ADD CONSTRAINT "DeviceRegistration_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CommunicationRoom" ADD CONSTRAINT "CommunicationRoom_caseId_fkey" FOREIGN KEY("caseId") REFERENCES "HelpCase"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "CommunicationRoom" ADD CONSTRAINT "CommunicationRoom_createdById_fkey" FOREIGN KEY("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SafeguardingCase" ADD CONSTRAINT "SafeguardingCase_reportId_fkey" FOREIGN KEY("reportId") REFERENCES "Report"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SafeguardingCase" ADD CONSTRAINT "SafeguardingCase_assignedToId_fkey" FOREIGN KEY("assignedToId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "PaymentAttempt" ADD CONSTRAINT "PaymentAttempt_transactionId_fkey" FOREIGN KEY("transactionId") REFERENCES "Transaction"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PaymentAttempt" ADD CONSTRAINT "PaymentAttempt_providerId_fkey" FOREIGN KEY("providerId") REFERENCES "PaymentProvider"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
